import math
def matmul(a,b):
    return [[sum(a[i][k]*b[k][j] for k in range(len(b))) for j in range(len(b[0]))] for i in range(len(a))]
def swiglu(x,w_gate,w_value,w_out):
    gate=matmul(x,w_gate); value=matmul(x,w_value)
    hidden=[[ (g/(1+math.exp(-g)))*v for g,v in zip(gr,vr)] for gr,vr in zip(gate,value)]
    return matmul(hidden,w_out)

