import torch
def rms_norm(x,gamma,eps=1e-6):
    if x.shape[-1]==0 or gamma.shape!=(x.shape[-1],) or eps<=0: raise ValueError('invalid shape or eps')
    scale=torch.rsqrt(x.square().mean(dim=-1,keepdim=True)+eps)
    return x*scale*gamma

